    def _handle_public_trust_center_acceptance_board(self, method: str, center_id: str, parts: list[str]) -> None:
        try:
            if len(parts) == 2:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_json(
                    {
                        "ok": True,
                        "center_id": center_id,
                        "report": self.public_trust_center_acceptance_board_store.read_report(center_id, default={}),
                        "conflict_report": self.public_trust_center_acceptance_board_store.read_conflict_report(center_id, default={}),
                        "policy": self.public_trust_center_acceptance_board_store.read_policy(center_id),
                        "summary": self.public_trust_center_acceptance_board_store.summary(center_id),
                    }
                )
                return
            subaction = parts[2] if len(parts) > 2 else ""
            if subaction == "download" and len(parts) == 3:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_file(self.public_trust_center_acceptance_board_store.zip_path(center_id), "application/zip", filename=f"musicforge-{center_id}-acceptance-board.zip")
                return
            if subaction == "signoff-archive" and len(parts) >= 4 and parts[3] == "download":
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_file(self.public_trust_center_acceptance_board_store.signoff_archive_zip_path(center_id), "application/zip", filename=f"musicforge-{center_id}-acceptance-board-signoff-archive.zip")
                return
            if subaction == "policy" and len(parts) == 3:
                if method == "GET":
                    policy = self.public_trust_center_acceptance_board_store.read_policy(center_id)
                    self._send_json({"ok": True, "center_id": center_id, "policy": policy})
                    return
                if method == "POST":
                    policy = self.public_trust_center_acceptance_board_store.save_policy(center_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "center_id": center_id, "policy": policy}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            payload = self._optional_json_body()
            if subaction == "refresh" and len(parts) == 3:
                report = self.public_trust_center_acceptance_board_store.refresh_report(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "report": report, "summary": self.public_trust_center_acceptance_board_store.summary(center_id)}, status=HTTPStatus.CREATED)
                return
            if subaction == "export" and len(parts) == 3:
                manifest = self.public_trust_center_acceptance_board_store.export_board(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "manifest": manifest, "summary": {"source_hash": manifest.get("source_hash"), "package_type": manifest.get("package_type")}}, status=HTTPStatus.CREATED)
                return
            if subaction == "zip" and len(parts) == 3:
                zip_info = self.public_trust_center_acceptance_board_store.build_zip(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "zip": zip_info})
                return
            if subaction == "verify" and len(parts) == 3:
                report = self.public_trust_center_acceptance_board_store.verify_zip(
                    center_id,
                    {
                        "strict": bool(payload.get("strict", True)),
                        "require_ready": bool(payload.get("require_ready", False)),
                        "require_quorum": bool(payload.get("require_quorum", False)),
                        "require_no_conflicts": bool(payload.get("require_no_conflicts", False)),
                        "min_accepted_count": int(payload.get("min_accepted_count") or 0),
                        "min_accepted_organizations": int(payload.get("min_accepted_organizations") or 0),
                        "required_roles": payload.get("required_roles") if isinstance(payload.get("required_roles"), list) else [],
                        "use_distribution_kit": bool(payload.get("use_distribution_kit", True)),
                    },
                )
                self._send_json({"ok": True, "center_id": center_id, "verification": report, "summary": report.get("summary", {})})
                return
            if subaction == "signoff-draft" and len(parts) == 3:
                draft = self.public_trust_center_acceptance_board_store.create_signoff_draft(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "draft": draft}, status=HTTPStatus.CREATED)
                return
            if subaction == "signoff" and len(parts) == 3:
                signoff = self.public_trust_center_acceptance_board_store.signoff(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "signoff": signoff, "summary": self.public_trust_center_acceptance_board_store.summary(center_id)}, status=HTTPStatus.CREATED)
                return
            if subaction == "change-request" and len(parts) == 3:
                change = self.public_trust_center_acceptance_board_store.create_change_request(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "change_request": change}, status=HTTPStatus.CREATED)
                return
            if subaction == "change-requests" and len(parts) >= 5 and parts[4] == "approve":
                change = self.public_trust_center_acceptance_board_store.approve_change_request(center_id, parts[3], payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "change_request": change})
                return
            if subaction == "reset-signoff" and len(parts) == 3:
                reset = self.public_trust_center_acceptance_board_store.reset_signoff(center_id, payload, now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "reset": reset, "summary": self.public_trust_center_acceptance_board_store.summary(center_id)})
                return
            if subaction == "signoff-archive" and len(parts) == 4:
                archive_action = parts[3]
                if archive_action == "export":
                    manifest = self.public_trust_center_acceptance_board_store.export_signoff_archive(center_id, payload, now=_utc_now())
                    self._send_json({"ok": True, "center_id": center_id, "manifest": manifest}, status=HTTPStatus.CREATED)
                    return
                if archive_action == "zip":
                    zip_info = self.public_trust_center_acceptance_board_store.build_signoff_archive_zip(center_id, payload, now=_utc_now())
                    self._send_json({"ok": True, "center_id": center_id, "zip": zip_info})
                    return
                if archive_action == "verify":
                    report = self.public_trust_center_acceptance_board_store.verify_signoff_archive_zip(center_id, {"strict": bool(payload.get("strict", True)), "require_signed": True, "require_current": True, "require_ready": True})
                    self._send_json({"ok": True, "center_id": center_id, "verification": report, "summary": report.get("summary", {})})
                    return
            self._send_error(HTTPStatus.NOT_FOUND, "Public Trust Center Acceptance Board route not found.")
        except PublicTrustCenterAcceptanceBoardNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except PublicTrustCenterAcceptanceBoardStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except PublicTrustCenterAcceptanceBoardError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
        except FileNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))

    def _handle_public_trust_center_distribution_kit_acceptance(self, method: str, center_id: str, parts: list[str]) -> None:
        try:
            if len(parts) == 3:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_json(
                    {
                        "ok": True,
                        "center_id": center_id,
                        "summary": self.public_trust_center_distribution_kit_acceptance_store.summary(center_id),
                        "responses": self.public_trust_center_distribution_kit_acceptance_store.list_responses(center_id),
                        "change_requests": self.public_trust_center_distribution_kit_acceptance_store.list_change_requests(center_id),
                    }
                )
                return
            if len(parts) == 4 and parts[3] == "template":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                template = self.public_trust_center_distribution_kit_acceptance_store.create_response_template(center_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, "template": template}, status=HTTPStatus.CREATED)
                return
            if len(parts) == 4 and parts[3] == "import":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                imported = self.public_trust_center_distribution_kit_acceptance_store.import_response(center_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "center_id": center_id, **imported}, status=HTTPStatus.CREATED)
                return
            if len(parts) >= 5 and parts[3] == "responses":
                response_id = parts[4]
                if len(parts) == 5:
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    response = self.public_trust_center_distribution_kit_acceptance_store.read_response(center_id, response_id)
                    self._send_json({"ok": True, "center_id": center_id, "response": response})
                    return
                response_action = parts[5] if len(parts) > 5 else ""
                if response_action == "verify" and len(parts) == 6:
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    report = self.public_trust_center_distribution_kit_acceptance_store.verify_response(center_id, response_id, now=_utc_now())
                    self._send_json({"ok": True, "center_id": center_id, "response_id": response_id, "verification": report, "summary": report.get("summary", {})})
                    return
                if response_action == "change-request-draft" and len(parts) == 6:
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    draft = self.public_trust_center_distribution_kit_acceptance_store.create_change_request_draft(center_id, response_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "center_id": center_id, "draft": draft}, status=HTTPStatus.CREATED)
                    return
                if response_action == "evidence" and len(parts) >= 7:
                    evidence_action = parts[6]
                    if evidence_action == "download" and len(parts) == 7:
                        if method != "GET":
                            self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                            return
                        evidence = self.public_trust_center_distribution_kit_acceptance_store.refresh_accepted_evidence(center_id, {"response_id": response_id}, now=_utc_now())
                        self._send_file(self.public_trust_center_distribution_kit_acceptance_store.evidence_zip_path(center_id, str(evidence.get("evidence_id") or "")), "application/zip", filename=f"musicforge-{center_id}-distribution-kit-accepted-evidence.zip")
                        return
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    if evidence_action == "export" and len(parts) == 7:
                        manifest = self.public_trust_center_distribution_kit_acceptance_store.export_accepted_evidence(center_id, response_id, now=_utc_now())
                        self._send_json({"ok": True, "center_id": center_id, "manifest": manifest}, status=HTTPStatus.CREATED)
                        return
                    if evidence_action == "zip" and len(parts) == 7:
                        zip_info = self.public_trust_center_distribution_kit_acceptance_store.build_accepted_evidence_zip(center_id, response_id, now=_utc_now())
                        evidence = self.public_trust_center_distribution_kit_acceptance_store.read_evidence(center_id, str(zip_info.get("evidence_id") or ""), default={})
                        self._send_json({"ok": True, "center_id": center_id, "zip": zip_info, "summary": public_trust_center_distribution_kit_accepted_evidence_summary(evidence)})
                        return
                    if evidence_action == "verify" and len(parts) == 7:
                        evidence = self.public_trust_center_distribution_kit_acceptance_store.refresh_accepted_evidence(center_id, {"response_id": response_id}, now=_utc_now())
                        report = self.public_trust_center_distribution_kit_acceptance_store.verify_accepted_evidence_zip(center_id, str(evidence.get("evidence_id") or ""), {"strict": True, "require_current": True})
                        self._send_json({"ok": True, "center_id": center_id, "verification": report, "summary": report.get("summary", {})})
                        return
            self._send_error(HTTPStatus.NOT_FOUND, "Public Trust Center Distribution Kit Acceptance route not found.")
        except PublicTrustCenterDistributionKitAcceptanceNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except PublicTrustCenterDistributionKitAcceptanceStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except PublicTrustCenterDistributionKitAcceptanceError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
        except FileNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))

    def _handle_release_portfolio_governance_queues(self, method: str, path: str) -> None:
        prefix = "/api/release-portfolio-governance-queues"
        tail = path[len(prefix):]
        try:
            if tail in {"", "/"}:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                query = parse_qs(urlparse(self.path).query)
                portfolio_id = str(query.get("portfolio_id", [""])[0] or "").strip() or None
                include_archived = str(query.get("include_archived", [""])[0]).lower() in {"1", "true", "yes"}
                queues = self.release_portfolio_governance_store.list_queues(portfolio_id=portfolio_id, include_archived=include_archived)
                self._send_json({"ok": True, "queues": queues, "summary": {"count": len(queues)}})
                return
            parts = [part for part in tail.strip("/").split("/") if part]
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Release Portfolio Governance Queue route not found.")
                return
            queue_id = parts[0]
            action = parts[1] if len(parts) > 1 else ""
            if len(parts) == 1:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                queue = self.release_portfolio_governance_store.get_queue(queue_id)
                execution = self.release_portfolio_governance_store.read_execution_report(queue_id, default={})
                self._send_json(
                    {
                        "ok": True,
                        "queue": queue,
                        "summary": queue_summary(queue, execution),
                        "signoff_summary": self.release_portfolio_governance_signoff_store.signoff_summary(queue_id),
                        "archive_summary": self.release_portfolio_governance_signoff_store.archive_summary(queue_id),
                        "change_request_summary": self.release_portfolio_governance_signoff_store.change_request_summary(queue_id),
                    }
                )
                return
            if action == "plan" and len(parts) == 2:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                plan = self.release_portfolio_governance_store.read_action_plan(queue_id, default={})
                self._send_json({"ok": True, "queue_id": queue_id, "action_plan": plan, "summary": {"item_count": len(plan.get("items", []) if isinstance(plan.get("items"), list) else [])}})
                return
            if action == "execution" and len(parts) == 2:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                execution = self.release_portfolio_governance_store.read_execution_report(queue_id, default={})
                self._send_json({"ok": True, "queue_id": queue_id, "execution_report": execution, "summary": execution.get("summary", {})})
                return
            if action == "manual-actions" and len(parts) == 2:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                manual = self.release_portfolio_governance_store.read_manual_action_list(queue_id, default={})
                self._send_json({"ok": True, "queue_id": queue_id, "manual_action_list": manual, "summary": {"count": len(manual.get("items", []) if isinstance(manual.get("items"), list) else [])}})
                return
            if action == "run-safe" and len(parts) == 2:
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                queue = self.release_portfolio_governance_store.run_safe_actions(queue_id, self._optional_json_body(), now=_utc_now())
                execution = self.release_portfolio_governance_store.read_execution_report(queue_id, default={})
                self._send_json({"ok": True, "queue": queue, "execution_report": execution, "summary": queue_summary(queue, execution)})
                return
            if action == "export" and len(parts) == 2:
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                manifest = self.release_portfolio_governance_store.export_queue(queue_id, now=_utc_now())
                self._send_json({"ok": True, "queue_id": queue_id, "manifest": manifest, "summary": manifest.get("summary", {})}, status=HTTPStatus.CREATED)
                return
            if action == "export" and len(parts) == 3 and parts[2] == "zip":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                zip_info = self.release_portfolio_governance_store.build_zip(queue_id, now=_utc_now())
                manifest = self.release_portfolio_governance_store.read_export_manifest(queue_id)
                self._send_json({"ok": True, "queue_id": queue_id, "zip": zip_info, "summary": manifest.get("summary", {})})
                return
            if action == "verify" and len(parts) == 2:
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                payload = self._optional_json_body()
                report = verify_release_portfolio_governance_package(
                    self.release_portfolio_governance_store.zip_path(queue_id),
                    strict=bool(payload.get("strict", False)),
                    require_manual_actions=bool(payload.get("require_manual_actions", False)),
                    require_no_blocked=bool(payload.get("require_no_blocked", False)),
                )
                write_release_portfolio_governance_verification_report(report, self.release_portfolio_governance_store.verification_report_path(queue_id))
                self._send_json({"ok": True, "queue_id": queue_id, "verification": report, "summary": release_portfolio_governance_verification_summary(report)})
                return
            if action == "signoff" and len(parts) == 2:
                if method == "GET":
                    signoff = self.release_portfolio_governance_signoff_store.read_signoff(queue_id, default={})
                    gate = self.release_portfolio_governance_signoff_store.gate(queue_id, {}, now=_utc_now())
                    self._send_json({"ok": True, "queue_id": queue_id, "signoff": signoff, "summary": self.release_portfolio_governance_signoff_store.signoff_summary(queue_id, signoff=signoff), "gate": gate})
                    return
                if method == "POST":
                    signoff = self.release_portfolio_governance_signoff_store.signoff(queue_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "queue_id": queue_id, "signoff": signoff, "summary": self.release_portfolio_governance_signoff_store.signoff_summary(queue_id, signoff=signoff)})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if action == "signoff" and len(parts) == 3 and parts[2] == "reset":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                signoff = self.release_portfolio_governance_signoff_store.reset_signoff(queue_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "queue_id": queue_id, "signoff": signoff, "summary": self.release_portfolio_governance_signoff_store.signoff_summary(queue_id, signoff=signoff)})
                return
            if action == "change-requests":
                if len(parts) == 2:
                    if method == "GET":
                        rows = self.release_portfolio_governance_signoff_store.list_change_requests(queue_id)
                        self._send_json({"ok": True, "queue_id": queue_id, "change_requests": rows, "summary": self.release_portfolio_governance_signoff_store.change_request_summary(queue_id)})
                        return
                    if method == "POST":
                        item = self.release_portfolio_governance_signoff_store.create_change_request(queue_id, self._optional_json_body(), now=_utc_now())
                        self._send_json({"ok": True, "queue_id": queue_id, "change_request": item, "summary": self.release_portfolio_governance_signoff_store.change_request_summary(queue_id)}, status=HTTPStatus.CREATED)
                        return
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                change_request_id = parts[2]
                if len(parts) == 3 and method == "GET":
                    item = self.release_portfolio_governance_signoff_store.get_change_request(queue_id, change_request_id)
                    self._send_json({"ok": True, "queue_id": queue_id, "change_request": item})
                    return
                if len(parts) == 4 and method == "POST" and parts[3] in {"approve", "reject", "archive"}:
                    item = self.release_portfolio_governance_signoff_store.update_change_request_status(queue_id, change_request_id, parts[3], self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "queue_id": queue_id, "change_request": item, "summary": self.release_portfolio_governance_signoff_store.change_request_summary(queue_id)})
                    return
                self._send_error(HTTPStatus.NOT_FOUND, "Release Portfolio Governance Change Request route not found.")
                return
            if action == "archive.zip" and len(parts) == 2:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self.release_portfolio_governance_store.get_queue(queue_id)
                self._send_file(self.release_portfolio_governance_signoff_store.archive_zip_path(queue_id), "application/zip", filename=f"musicforge-{queue_id}-portfolio-governance-archive.zip")
                return
            if action == "archive" and len(parts) >= 2:
                if len(parts) == 2 and method == "GET":
                    manifest = self.release_portfolio_governance_signoff_store.read_archive_manifest(queue_id)
                    self._send_json({"ok": True, "queue_id": queue_id, "manifest": manifest, "summary": self.release_portfolio_governance_signoff_store.archive_summary(queue_id)})
                    return
                if len(parts) == 3 and parts[2] == "export":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    manifest = self.release_portfolio_governance_signoff_store.export_archive(queue_id, now=_utc_now())
                    self._send_json({"ok": True, "queue_id": queue_id, "manifest": manifest, "summary": manifest.get("summary", {})}, status=HTTPStatus.CREATED)
                    return
                if len(parts) == 3 and parts[2] == "zip":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    zip_info = self.release_portfolio_governance_signoff_store.build_archive_zip(queue_id, now=_utc_now())
                    manifest = self.release_portfolio_governance_signoff_store.read_archive_manifest(queue_id)
                    self._send_json({"ok": True, "queue_id": queue_id, "zip": zip_info, "summary": manifest.get("summary", {})})
                    return
                if len(parts) == 3 and parts[2] == "verify":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    payload = self._optional_json_body()
                    report = verify_release_portfolio_governance_archive_package(
                        self.release_portfolio_governance_signoff_store.archive_zip_path(queue_id),
                        strict=bool(payload.get("strict", False)),
                        require_signed=bool(payload.get("require_signed", False)),
                        require_no_force=bool(payload.get("require_no_force", False)),
                    )
                    write_release_portfolio_governance_archive_verification_report(report, self.release_portfolio_governance_signoff_store.archive_verification_report_path(queue_id))
                    self._send_json({"ok": True, "queue_id": queue_id, "verification": report, "summary": release_portfolio_governance_archive_verification_summary(report)})
                    return
            if action == "download" and len(parts) == 2:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self.release_portfolio_governance_store.get_queue(queue_id)
                self._send_file(self.release_portfolio_governance_store.zip_path(queue_id), "application/zip", filename=f"musicforge-{queue_id}-portfolio-governance.zip")
                return
            if action == "archive" and len(parts) == 2:
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                queue = self.release_portfolio_governance_store.archive(queue_id, now=_utc_now())
                self._send_json({"ok": True, "queue": queue, "summary": queue_summary(queue)})
                return
            self._send_error(HTTPStatus.NOT_FOUND, "Release Portfolio Governance Queue route not found.")
        except ReleasePortfolioGovernanceNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except ReleasePortfolioGovernanceStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except ReleasePortfolioGovernanceSignoffNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except ReleasePortfolioGovernanceSignoffStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except ReleasePortfolioGovernanceSignoffError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
        except ReleasePortfolioGovernanceError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
        except FileNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))

    def _handle_release_operations_runbooks(self, method: str, release_id: str, tail: str) -> None:
        if tail in {"", "/"}:
            if method == "GET":
                query = parse_qs(urlparse(self.path).query)
                include_archived = str(query.get("include_archived", [""])[0]).lower() in {"1", "true", "yes"}
                runbooks = self.release_operations_runbook_store.list_runbooks(release_id, include_archived=include_archived)
                self._send_json({"ok": True, "release_id": release_id, "runbooks": runbooks, "summary": {"count": len(runbooks)}})
                return
            if method == "POST":
                runbook = self.release_operations_runbook_store.create_from_operations_report(release_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "runbook": runbook, "summary": runbook_summary(runbook)}, status=HTTPStatus.CREATED)
                return
            self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
            return
        parts = [part for part in tail.strip("/").split("/") if part]
        if not parts:
            self._send_error(HTTPStatus.NOT_FOUND, "Release Operations Runbook route not found.")
            return
        runbook_id = parts[0]
        if len(parts) == 1:
            if method != "GET":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            runbook = self.release_operations_runbook_store.get_runbook(release_id, runbook_id)
            self._send_json({"ok": True, "release_id": release_id, "runbook": runbook, "summary": runbook_summary(runbook)})
            return
        action = parts[1]
        if len(parts) == 2 and action == "run-safe":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            runbook = self.release_operations_runbook_store.run_safe_actions(release_id, runbook_id, self._optional_json_body(), now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, "runbook": runbook, "summary": runbook_summary(runbook)})
            return
        if len(parts) == 2 and action == "refresh-stale":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            result = self.release_operations_runbook_store.refresh_stale_status(release_id, runbook_id, now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, **result, "summary": runbook_summary(result.get("runbook", {}))})
            return
        if len(parts) == 2 and action == "archive":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            runbook = self.release_operations_runbook_store.archive_runbook(release_id, runbook_id, now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, "runbook": runbook, "summary": runbook_summary(runbook)})
            return
        if len(parts) == 2 and action == "export":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            manifest = self.release_operations_runbook_store.export_runbook(release_id, runbook_id, now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, "runbook_id": runbook_id, "manifest": manifest, "summary": manifest.get("summary", {})}, status=HTTPStatus.CREATED)
            return
        if len(parts) == 3 and action == "export" and parts[2] == "zip":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            zip_info = self.release_operations_runbook_store.build_zip(release_id, runbook_id, now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, "runbook_id": runbook_id, "zip": zip_info})
            return
        if len(parts) == 2 and action == "export.zip":
            if method != "GET":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            self._send_file(self.release_operations_runbook_store.zip_path(release_id, runbook_id), "application/zip", filename=f"musicforge-{release_id}-{runbook_id}-runbook.zip")
            return
        if len(parts) == 2 and action == "verify":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            payload = self._optional_json_body()
            report = verify_release_operations_runbook_package(
                self.release_operations_runbook_store.zip_path(release_id, runbook_id),
                strict=bool(payload.get("strict", False)),
                require_completed=bool(payload.get("require_completed", False)),
                require_current=bool(payload.get("require_current", False)),
            )
            write_release_operations_runbook_verification_report(report, self.release_operations_runbook_store.runbook_dir(release_id, runbook_id) / "runbook-verification-report.json")
            self._send_json({"ok": True, "release_id": release_id, "runbook_id": runbook_id, "verification": report, "summary": release_operations_runbook_verification_summary(report)})
            return
        if len(parts) == 4 and action == "items" and parts[3] == "retry":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            runbook = self.release_operations_runbook_store.retry_item(release_id, runbook_id, parts[2], now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, "runbook": runbook, "summary": runbook_summary(runbook)})
            return
        if len(parts) == 4 and action == "items" and parts[3] == "waive":
            if method != "POST":
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            runbook = self.release_operations_runbook_store.waive_item(release_id, runbook_id, parts[2], self._optional_json_body(), now=_utc_now())
            self._send_json({"ok": True, "release_id": release_id, "runbook": runbook, "summary": runbook_summary(runbook)})
            return
        self._send_error(HTTPStatus.NOT_FOUND, "Release Operations Runbook route not found.")

    def _get_or_refresh_release_qa(self, release_id: str, *, refresh: bool, options: dict[str, Any]) -> dict[str, Any]:
        document = self.release_store.get_release(release_id)
        if not refresh:
            existing = self.release_store.read_qa(release_id, default={})
            if existing:
                current_hash = release_source_hash(document, project_store=self.project_store, release_store=self.release_store)
                if str(existing.get("source_hash") or "") != current_hash:
                    return mark_release_qa_stale(existing, current_source_hash=current_hash)
                return existing
        report = build_release_qa_report(release=document, release_store=self.release_store, project_store=self.project_store, options=options, now=_utc_now())
        report = self.release_store.write_qa(release_id, report)
        self.release_store.update_qa_summary(release_id, release_qa_summary(report))
        return report

    def _get_or_refresh_release_metadata_qa(self, release_id: str, *, refresh: bool) -> dict[str, Any]:
        document = self.release_store.get_release(release_id)
        metadata = read_release_metadata(self.release_store, release_id, default={})
        if not metadata:
            report = build_release_metadata_qa_report(release=document, metadata={}, now=_utc_now())
            return write_release_metadata_qa(self.release_store, release_id, report)
        if not refresh:
            existing = read_release_metadata_qa(self.release_store, release_id, default={})
            if existing:
                current_hash = release_metadata_source_hash(document, metadata)
                if str(existing.get("source_hash") or "") != current_hash:
                    return mark_release_metadata_qa_stale(existing, current_source_hash=current_hash)
                return existing
        report = build_release_metadata_qa_report(release=document, metadata=metadata, now=_utc_now())
        return write_release_metadata_qa(self.release_store, release_id, report)

    def _handle_release_audio_qa(self, method: str, release_id: str) -> None:
        if method == "GET":
            report = read_release_audio_qa(self.release_store, release_id, default={})
            self._send_json({"ok": True, "release_id": release_id, "audio_qa": report, "summary": release_audio_summary(report)})
            return
        if method == "POST":
            payload = self._optional_json_body()
            report = build_release_audio_qa_report(
                release=self.release_store.get_release(release_id),
                release_store=self.release_store,
                project_store=self.project_store,
                require_audio=bool(payload.get("require_audio", True)),
                now=_utc_now(),
            )
            report = write_release_audio_qa(self.release_store, release_id, report)
            self.release_store.append_event(release_id, "release_audio_qa_refreshed", {"status": report.get("status")})
            self._send_json({"ok": True, "release_id": release_id, "audio_qa": report, "summary": release_audio_summary(report)})
            return
        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")

    def _handle_release_audio_reviews(self, method: str, release_id: str, tail: str) -> None:
        try:
            if tail in {"", "/"}:
                if method == "GET":
                    reviews = self.audio_review_store.list_reviews(release_id)
                    summary = self.audio_review_store.build_summary(release_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "reviews": reviews, "summary": audio_review_summary_public(summary)})
                    return
                if method == "POST":
                    review = self.audio_review_store.create_review(release_id, self._read_json_body(), now=_utc_now())
                    summary = self.audio_review_store.build_summary(release_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "review": review, "summary": audio_review_summary_public(summary)}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if tail == "/summary":
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                summary = self.audio_review_store.build_summary(release_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "summary": audio_review_summary_public(summary), "audio_review_summary": summary})
                return
            if tail == "/refresh-summary":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self.audio_review_store._ensure_release_mutable(release_id)
                summary = self.audio_review_store.write_summary(release_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "summary": audio_review_summary_public(summary), "audio_review_summary": summary})
                return
            if tail == "/import-human-review-pack":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_review_store.import_human_review_pack(release_id, self._read_json_body(), acceptance_store=self.acceptance_store, now=_utc_now())
                self._send_json({"ok": True, **result}, status=HTTPStatus.CREATED)
                return
            parts = [part for part in tail.strip("/").split("/") if part]
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Audio review route not found.")
                return
            review_id = parts[0]
            if len(parts) == 1:
                if method == "GET":
                    review = self.audio_review_store.read_review(release_id, review_id)
                    self._send_json({"ok": True, "release_id": release_id, "review": review, "summary": audio_review_summary_public(self.audio_review_store.build_summary(release_id, now=_utc_now()))})
                    return
                if method == "POST":
                    review = self.audio_review_store.update_review(release_id, review_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "review": review, "summary": audio_review_summary_public(self.audio_review_store.build_summary(release_id, now=_utc_now()))})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[1] == "delete":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_review_store.delete_review(release_id, review_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, **result})
                return
            if len(parts) == 2 and parts[1] == "refresh":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                review = self.audio_review_store.refresh_review(release_id, review_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "review": review, "summary": audio_review_summary_public(self.audio_review_store.build_summary(release_id, now=_utc_now()))})
                return
            if len(parts) == 4 and parts[1] == "markers" and parts[3] == "create-review-task":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_review_store.create_review_task_from_marker(release_id, review_id, parts[2], self._optional_json_body(), now=_utc_now())
                status = HTTPStatus.CREATED if result.get("status") == "created" else HTTPStatus.OK
                self._send_json({"ok": True, "release_id": release_id, **result}, status=status)
                return
            if len(parts) == 4 and parts[1] == "markers" and parts[3] == "mix-patch-draft":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = MixRenderStore(self.project_store, self.store).marker_mix_patch_draft(
                    release_store=self.release_store,
                    audio_review_store=self.audio_review_store,
                    release_id=release_id,
                    review_id=review_id,
                    marker_id=parts[2],
                    payload=self._optional_json_body(),
                    now=_utc_now(),
                )
                self._send_json({"ok": True, "release_id": release_id, **result}, status=HTTPStatus.CREATED)
                return
            self._send_error(HTTPStatus.NOT_FOUND, "Audio review route not found.")
        except AudioReviewEvidenceNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except AudioReviewEvidenceStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except MixControlStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except MixControlError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
        except AudioReviewEvidenceError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_release_audio_revisions(self, method: str, release_id: str, tail: str) -> None:
        try:
            if tail in {"", "/"}:
                if method == "GET":
                    sessions = self.audio_revision_store.list_sessions(release_id)
                    summary = self.audio_revision_store.gate(release_id, required=False, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "sessions": sessions, "summary": summary})
                    return
                if method == "POST":
                    session = self.audio_revision_store.create_session(release_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "session": session, "summary": self.audio_revision_store.gate(release_id, required=False, now=_utc_now())}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if tail == "/summary":
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                summary = self.audio_revision_store.gate(release_id, required=False, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "summary": summary})
                return
            parts = [part for part in tail.strip("/").split("/") if part]
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Audio revision route not found.")
                return
            session_id = parts[0]
            if len(parts) == 1:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                session = self.audio_revision_store.read_session(release_id, session_id)
                issues = self.audio_revision_store.list_issues(release_id, session_id)
                candidates = self.audio_revision_store.list_candidates(release_id, session_id)
                closeout = self.audio_revision_store.read_closeout(release_id, session_id, default={})
                self._send_json({"ok": True, "release_id": release_id, "session": session, "issues": issues, "candidates": candidates, "closeout": closeout})
                return
            if len(parts) == 2 and parts[1] == "refresh":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_revision_store.refresh_recheck_status(release_id, session_id, now=_utc_now())
                self._send_json({"ok": True, **result})
                return
            if len(parts) == 2 and parts[1] == "close":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_revision_store.close_session(release_id, session_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, **result})
                return
            if len(parts) == 2 and parts[1] == "archive":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                session = self.audio_revision_store.archive_session(release_id, session_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "session": session})
                return
            if len(parts) >= 2 and parts[1] == "issues":
                if len(parts) == 2:
                    if method == "GET":
                        self._send_json({"ok": True, "release_id": release_id, "session_id": session_id, "issues": self.audio_revision_store.list_issues(release_id, session_id)})
                        return
                    if method == "POST":
                        issue = self.audio_revision_store.create_issue(release_id, session_id, self._read_json_body(), now=_utc_now())
                        self._send_json({"ok": True, "release_id": release_id, "issue": issue}, status=HTTPStatus.CREATED)
                        return
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                issue_id = parts[2]
                if len(parts) == 3:
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    issue = self.audio_revision_store.read_issue(release_id, session_id, issue_id)
                    self._send_json({"ok": True, "release_id": release_id, "issue": issue})
                    return
                if len(parts) == 4 and parts[3] in {"waive", "reopen"}:
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    if parts[3] == "waive":
                        issue = self.audio_revision_store.waive_issue(release_id, session_id, issue_id, self._optional_json_body(), now=_utc_now())
                    else:
                        issue = self.audio_revision_store.reopen_issue(release_id, session_id, issue_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "issue": issue})
                    return
                if len(parts) == 5 and parts[3] == "candidates" and parts[4] == "generate":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    result = self.audio_revision_store.generate_candidates(release_id, session_id, issue_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, **result}, status=HTTPStatus.CREATED)
                    return
            if len(parts) >= 2 and parts[1] == "candidates":
                if len(parts) == 2:
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    self._send_json({"ok": True, "release_id": release_id, "session_id": session_id, "candidates": self.audio_revision_store.list_candidates(release_id, session_id)})
                    return
                candidate_id = parts[2]
                if len(parts) == 3:
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    candidate = self.audio_revision_store.read_candidate(release_id, session_id, candidate_id)
                    self._send_json({"ok": True, "release_id": release_id, "candidate": candidate})
                    return
                if len(parts) == 4 and parts[3] in {"midi", "audio"}:
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    path, media_type, filename = self.audio_revision_store.download_candidate_artifact(release_id, session_id, candidate_id, "midi" if parts[3] == "midi" else "audio")
                    self._send_file(path, media_type, filename=filename)
                    return
                if len(parts) == 4 and parts[3] in {"review", "select", "apply"}:
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    if parts[3] == "review":
                        candidate = self.audio_revision_store.review_candidate(release_id, session_id, candidate_id, self._read_json_body(), now=_utc_now())
                        self._send_json({"ok": True, "release_id": release_id, "candidate": candidate})
                        return
                    if parts[3] == "select":
                        candidate = self.audio_revision_store.select_candidate(release_id, session_id, candidate_id, now=_utc_now())
                        self._send_json({"ok": True, "release_id": release_id, "candidate": candidate})
                        return
                    result = self.audio_revision_store.apply_candidate(release_id, session_id, candidate_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, **result})
                    return
            self._send_error(HTTPStatus.NOT_FOUND, "Audio revision route not found.")
        except AudioRevisionNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except AudioRevisionStateError as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except AudioRevisionError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
        except (MixControlStateError, ReleaseStateError) as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except (MixControlError, ValueError) as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_release_mastering(self, method: str, release_id: str, tail: str) -> None:
        try:
            if tail in {"", "/"}:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_json(
                    {
                        "ok": True,
                        "release_id": release_id,
                        "summary": self.mastering_store.get_summary(release_id, now=_utc_now()),
                        "analysis": self.mastering_store.read_analysis(release_id, default={}),
                        "plan": self.mastering_store.read_plan(release_id, default={}),
                        "candidates": self.mastering_store.list_candidates(release_id),
                        "selected_candidate": self.mastering_store.read_selected_candidate(release_id, default={}),
                    }
                )
                return
            if tail == "/analyze":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                analysis = self.mastering_store.analyze(release_id, self._optional_json_body(), now=_utc_now())
                self.release_store.append_event(release_id, "release_mastering_analyzed", {"status": analysis.get("status"), "profile_id": analysis.get("profile_id")})
                self._send_json({"ok": True, "release_id": release_id, "analysis": analysis, "summary": self.mastering_store.get_summary(release_id, now=_utc_now())})
                return
            if tail == "/plan":
                if method == "GET":
                    plan = self.mastering_store.read_plan(release_id, default={})
                    self._send_json({"ok": True, "release_id": release_id, "plan": plan, "summary": self.mastering_store.get_summary(release_id, now=_utc_now())})
                    return
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                plan = self.mastering_store.build_plan(release_id, self._optional_json_body(), now=_utc_now())
                self.release_store.append_event(release_id, "release_mastering_plan_created", {"action_count": plan.get("summary", {}).get("action_count")})
                self._send_json({"ok": True, "release_id": release_id, "plan": plan, "summary": self.mastering_store.get_summary(release_id, now=_utc_now())})
                return
            if tail == "/candidates":
                if method == "GET":
                    self._send_json({"ok": True, "release_id": release_id, "candidates": self.mastering_store.list_candidates(release_id), "summary": self.mastering_store.get_summary(release_id, now=_utc_now())})
                    return
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                candidate = self.mastering_store.render_candidate(release_id, self._optional_json_body(), now=_utc_now())
                self.release_store.append_event(release_id, "release_mastering_candidate_rendered", {"candidate_id": candidate.get("candidate_id"), "status": candidate.get("status")})
                self._send_json({"ok": True, "release_id": release_id, "candidate": candidate, "summary": self.mastering_store.get_summary(release_id, now=_utc_now())}, status=HTTPStatus.CREATED)
                return
            if tail == "/refresh":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.mastering_store.refresh(release_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, **result})
                return
            if tail == "/reset":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.mastering_store.reset(release_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, **result})
                return
            parts = [part for part in tail.strip("/").split("/") if part]
            if len(parts) >= 2 and parts[0] == "candidates":
                candidate_id = parts[1]
                if len(parts) == 2:
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    candidate = self.mastering_store.read_candidate(release_id, candidate_id)
                    self._send_json({"ok": True, "release_id": release_id, "candidate": candidate})
                    return
                if len(parts) == 5 and parts[2] == "tracks" and parts[4] == "audio":
                    if method != "GET":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    path = self.mastering_store.candidate_audio_path(release_id, candidate_id, parts[3])
                    self._send_file(path, "audio/wav", filename=f"{parts[3]}-mastered.wav")
                    return
                if len(parts) == 3 and parts[2] in {"review", "select"}:
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    if parts[2] == "review":
                        candidate = self.mastering_store.review_candidate(release_id, candidate_id, self._read_json_body(), now=_utc_now())
                    else:
                        candidate = self.mastering_store.select_candidate(release_id, candidate_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "candidate": candidate, "summary": self.mastering_store.get_summary(release_id, now=_utc_now())})
                    return
            self._send_error(HTTPStatus.NOT_FOUND, "Mastering route not found.")
        except MasteringNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except (MasteringStateError, ReleaseStateError) as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except (MasteringQAError, MasteringProfileError, ValueError) as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_release_encoded_audio(self, method: str, release_id: str, tail: str) -> None:
        try:
            if tail in {"", "/"}:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_json({"ok": True, "release_id": release_id, "summary": self.audio_encoding_store.get_summary(release_id, now=_utc_now()), "formats": self.audio_encoding_store.list_manifests(release_id)})
                return
            if tail == "/render":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_encoding_store.render(release_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, **result}, status=HTTPStatus.CREATED)
                return
            if tail == "/render-format":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                payload = self._optional_json_body()
                profile_id = str(payload.get("profile_id") or "").strip()
                if not profile_id:
                    self._send_error(HTTPStatus.BAD_REQUEST, "profile_id is required.")
                    return
                manifest = self.audio_encoding_store.render_format(release_id, profile_id, payload, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "manifest": manifest, "summary": self.audio_encoding_store.get_summary(release_id, now=_utc_now())}, status=HTTPStatus.CREATED)
                return
            if tail == "/verify":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_encoding_store.verify(release_id, self._optional_json_body())
                self._send_json({"ok": True, **result})
                return
            if tail == "/reset":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                result = self.audio_encoding_store.reset(release_id, self._optional_json_body())
                self._send_json({"ok": True, **result})
                return
            parts = [part for part in tail.strip("/").split("/") if part]
            if len(parts) == 1 and parts[0] == "health":
                if method == "GET":
                    self._send_json({"ok": True, "release_id": release_id, "health": self.encoded_audio_acceptance_store.list_health(release_id)})
                    return
                if method == "POST":
                    payload = self._optional_json_body()
                    result = self.encoded_audio_acceptance_store.refresh_health(release_id, normalize_required_profiles(payload.get("profile_ids") or payload.get("profiles") or payload.get("required_audio_format_profiles") or []), now=_utc_now())
                    self._send_json({"ok": True, **result})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[0] == "health" and method == "GET":
                report = self.encoded_audio_acceptance_store.read_health(release_id, parts[1])
                self._send_json({"ok": True, "release_id": release_id, "profile_id": parts[1], "health": report})
                return
            if len(parts) == 1 and parts[0] == "reviews":
                if method == "GET":
                    reviews = self.encoded_audio_acceptance_store.list_reviews(release_id)
                    self._send_json({"ok": True, "release_id": release_id, "reviews": reviews})
                    return
                if method == "POST":
                    review = self.encoded_audio_acceptance_store.create_review(release_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "review": review}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[0] == "reviews":
                review_id = parts[1]
                if method == "GET":
                    review = self.encoded_audio_acceptance_store.read_review(release_id, review_id)
                    self._send_json({"ok": True, "release_id": release_id, "review": review})
                    return
                if method in {"POST", "PATCH"}:
                    review = self.encoded_audio_acceptance_store.update_review(release_id, review_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "review": review})
                    return
                if method == "DELETE":
                    result = self.encoded_audio_acceptance_store.delete_review(release_id, review_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, **result})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 1 and parts[0] == "acceptance":
                if method == "GET":
                    payload_profiles = []
                    summary = self.encoded_audio_acceptance_store.build_summary(release_id, required_profiles=payload_profiles, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "summary": summary})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[0] == "acceptance" and parts[1] == "refresh":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                payload = self._optional_json_body()
                summary = self.encoded_audio_acceptance_store.write_summary(release_id, required_profiles=normalize_required_profiles(payload.get("profile_ids") or payload.get("profiles") or payload.get("required_audio_format_profiles") or []), now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "summary": summary})
                return
            if len(parts) == 2 and parts[0] == "formats" and method == "GET":
                manifest = self.audio_encoding_store.read_manifest(release_id, parts[1])
                self._send_json({"ok": True, "release_id": release_id, "manifest": manifest})
                return
            if len(parts) == 5 and parts[0] == "formats" and parts[2] == "tracks" and parts[4] == "audio" and method == "GET":
                manifest = self.audio_encoding_store.read_manifest(release_id, parts[1])
                track = next((row for row in manifest.get("tracks", []) if isinstance(row, dict) and row.get("track_id") == parts[3]), None)
                if not track:
                    self._send_error(HTTPStatus.NOT_FOUND, "Encoded track audio not found.")
                    return
                path = self.audio_encoding_store.track_audio_path(release_id, parts[1], parts[3])
                self._send_file(path, "application/octet-stream", filename=path.name)
                return
            self._send_error(HTTPStatus.NOT_FOUND, "Encoded audio route not found.")
        except (ReleaseNotFoundError, AudioEncodingNotFoundError, FileNotFoundError) as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except (EncodedAudioAcceptanceNotFoundError,) as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except (ReleaseStateError, AudioEncodingStateError, EncodedAudioAcceptanceStateError) as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except (AudioEncodingError, AudioEncodingProfileError, EncodedAudioAcceptanceError, ValueError) as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_audio_profiles_route(self, method: str, path: str) -> None:
        try:
            if path == "/api/audio/profiles":
                if method == "GET":
                    profiles = [profile.public_summary() for profile in self.audio_profile_store.list_profiles(include_hidden=True)]
                    self._send_json({"ok": True, "profiles": profiles})
                    return
                if method == "POST":
                    profile = self.audio_profile_store.upsert_profile(self._read_json_body())
                    self._send_json({"ok": True, "profile": profile.public_summary()}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            rest = path.removeprefix("/api/audio/profiles/").strip("/")
            parts = rest.split("/") if rest else []
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Audio profile route not found.")
                return
            profile_id = parts[0]
            if len(parts) == 1:
                if method == "GET":
                    profile = self.audio_profile_store.get_profile(profile_id)
                    self._send_json({"ok": True, "profile": profile.public_summary()})
                    return
                if method == "POST":
                    profile = self.audio_profile_store.upsert_profile({**self._read_json_body(), "profile_id": profile_id})
                    self._send_json({"ok": True, "profile": profile.public_summary()})
                    return
            if len(parts) == 2 and method == "POST":
                action = parts[1]
                if action == "test":
                    self._send_json({"ok": True, **self.audio_profile_store.test_profile(profile_id)})
                    return
                if action == "set-default":
                    profile = self.audio_profile_store.set_default(profile_id)
                    self._send_json({"ok": True, "profile": profile.public_summary()})
                    return
                if action == "hide":
                    profile = self.audio_profile_store.hide(profile_id, hidden=True)
                    self._send_json({"ok": True, "profile": profile.public_summary()})
                    return
                if action == "unhide":
                    profile = self.audio_profile_store.hide(profile_id, hidden=False)
                    self._send_json({"ok": True, "profile": profile.public_summary()})
                    return
            self._send_error(HTTPStatus.NOT_FOUND, "Audio profile route not found.")
        except AudioProfileNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except AudioProfileError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_mastering_profiles_route(self, method: str, path: str) -> None:
        try:
            if path == "/api/mastering/profiles":
                if method == "GET":
                    profiles = [profile.to_dict() for profile in self.mastering_profile_store.list_profiles(include_builtins=True)]
                    self._send_json({"ok": True, "profiles": profiles})
                    return
                if method == "POST":
                    profile = self.mastering_profile_store.create_profile(self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "profile": profile.to_dict()}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            rest = path.removeprefix("/api/mastering/profiles/").strip("/")
            parts = rest.split("/") if rest else []
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Mastering profile route not found.")
                return
            profile_id = parts[0]
            if len(parts) == 1:
                if method == "GET":
                    profile = self.mastering_profile_store.get_profile(profile_id)
                    self._send_json({"ok": True, "profile": profile.to_dict()})
                    return
                if method == "PATCH":
                    profile = self.mastering_profile_store.update_profile(profile_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "profile": profile.to_dict()})
                    return
                if method == "DELETE":
                    self.mastering_profile_store.delete_profile(profile_id)
                    self._send_json({"ok": True, "deleted": True, "profile_id": profile_id})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[1] == "clone":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                profile = self.mastering_profile_store.clone_profile(profile_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "profile": profile.to_dict()}, status=HTTPStatus.CREATED)
                return
            self._send_error(HTTPStatus.NOT_FOUND, "Mastering profile route not found.")
        except MasteringProfileNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except MasteringProfileError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_audio_encoding_route(self, method: str, path: str) -> None:
        try:
            if path == "/api/audio-encoding/config":
                if method == "GET":
                    self._send_json({"ok": True, "config": self.audio_encoding_store.read_config().public_summary()})
                    return
                if method == "POST":
                    config = self.audio_encoding_store.write_config(self._read_json_body())
                    self._send_json({"ok": True, "config": config})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if path == "/api/audio-encoding/config/test":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_json({"ok": True, **self.audio_encoding_store.test_config()})
                return
            if path == "/api/audio-encoding/config/reset":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                self._send_json({"ok": True, "config": self.audio_encoding_store.reset_config()})
                return
            if path == "/api/audio-encoding/profiles":
                if method == "GET":
                    profiles = [profile.to_dict() for profile in self.audio_encoding_profile_store.list_profiles(include_builtins=True)]
                    self._send_json({"ok": True, "profiles": profiles})
                    return
                if method == "POST":
                    profile = self.audio_encoding_profile_store.create_profile(self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "profile": profile.to_dict()}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            rest = path.removeprefix("/api/audio-encoding/profiles/").strip("/")
            parts = rest.split("/") if rest else []
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Audio encoding profile route not found.")
                return
            profile_id = parts[0]
            if len(parts) == 1:
                if method == "GET":
                    profile = self.audio_encoding_profile_store.get_profile(profile_id)
                    self._send_json({"ok": True, "profile": profile.to_dict()})
                    return
                if method == "PATCH":
                    profile = self.audio_encoding_profile_store.update_profile(profile_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "profile": profile.to_dict()})
                    return
                if method == "DELETE":
                    self.audio_encoding_profile_store.delete_profile(profile_id)
                    self._send_json({"ok": True, "deleted": True, "profile_id": profile_id})
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[1] == "clone":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                profile = self.audio_encoding_profile_store.clone_profile(profile_id, self._optional_json_body(), now=_utc_now())
                self._send_json({"ok": True, "profile": profile.to_dict()}, status=HTTPStatus.CREATED)
                return
            self._send_error(HTTPStatus.NOT_FOUND, "Audio encoding profile route not found.")
        except AudioEncodingProfileNotFoundError as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except AudioEncodingProfileError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_release_format_decisions(self, method: str, release_id: str, tail: str) -> None:
        try:
            if tail in {"", "/"}:
                if method == "GET":
                    sessions = self.format_decision_store.list_sessions(release_id, include_archived=True)
                    active = self.format_decision_store.read_active_session(release_id, default={})
                    self._send_json({"ok": True, "release_id": release_id, "sessions": sessions, "active_session": active})
                    return
                if method == "POST":
                    session = self.format_decision_store.create_session(release_id, self._optional_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "session": session}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            parts = [part for part in tail.strip("/").split("/") if part]
            if not parts:
                self._send_error(HTTPStatus.NOT_FOUND, "Format decision route not found.")
                return
            session_id = parts[0]
            if len(parts) == 1:
                if method == "GET":
                    session = self.format_decision_store.read_session(release_id, session_id)
                    matrix = self.format_decision_store.read_matrix(release_id, session_id, default={})
                    recommendation = self.format_decision_store.read_recommendation(release_id, session_id, default={})
                    report = self.format_decision_store.read_report(release_id, session_id, default={})
                    self._send_json({"ok": True, "release_id": release_id, "session": session, "matrix": matrix, "recommendation": recommendation, "report": report})
                    return
                if method == "DELETE":
                    session = self.format_decision_store.archive_session(release_id, session_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "session": session})
                    return
            if len(parts) == 2 and parts[1] == "matrix":
                if method == "GET":
                    matrix = self.format_decision_store.read_matrix(release_id, session_id)
                    self._send_json({"ok": True, "release_id": release_id, "matrix": matrix})
                    return
                if method == "POST":
                    matrix = self.format_decision_store.build_matrix(release_id, session_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "matrix": matrix})
                    return
            if len(parts) == 2 and parts[1] == "recommend":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                recommendation = self.format_decision_store.build_recommendation(release_id, session_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "recommendation": recommendation})
                return
            if len(parts) == 2 and parts[1] == "recommendation":
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                recommendation = self.format_decision_store.read_recommendation(release_id, session_id)
                self._send_json({"ok": True, "release_id": release_id, "recommendation": recommendation})
                return
            if len(parts) == 2 and parts[1] == "select":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                session = self.format_decision_store.select_profiles(release_id, session_id, self._read_json_body(), now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "session": session})
                return
            if len(parts) == 2 and parts[1] == "report":
                if method == "GET":
                    report = self.format_decision_store.read_report(release_id, session_id)
                    self._send_json({"ok": True, "release_id": release_id, "report": report})
                    return
                if method == "POST":
                    report = self.format_decision_store.build_report(release_id, session_id, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "report": report})
                    return
            if len(parts) == 2 and parts[1] == "activate":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                active = self.format_decision_store.activate_session(release_id, session_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "active_session": active})
                return
            if len(parts) == 2 and parts[1] == "gate":
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                payload = self._optional_json_body()
                gate = self.format_decision_store.gate(
                    release_id,
                    required=True,
                    session_id=session_id,
                    required_profiles=normalize_required_profiles(payload.get("required_audio_format_profiles") or payload.get("profiles") or []),
                )
                self._send_json({"ok": True, "release_id": release_id, "gate": gate})
                return
            self._send_error(HTTPStatus.NOT_FOUND, "Format decision route not found.")
        except (ReleaseNotFoundError, FormatDecisionNotFoundError, FileNotFoundError) as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except (ReleaseStateError, FormatDecisionStateError) as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except (FormatDecisionError, ValueError) as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _handle_release_rights(self, method: str, release_id: str, tail: str) -> None:
        try:
            parts = [part for part in tail.strip("/").split("/") if part]
            if not parts:
                if method != "GET":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                report = self.rights_clearance_store.read_report(release_id, default={})
                self._send_json({"ok": True, "release_id": release_id, "report": report, "parties": self.rights_clearance_store.list_parties(release_id)})
                return
            if parts == ["refresh"]:
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                report = self.rights_clearance_store.refresh_report(release_id, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "report": report})
                return
            if parts == ["gate"]:
                if method != "POST":
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                gate = self.rights_clearance_store.gate(release_id, required=True, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "gate": gate})
                return
            if parts == ["parties"]:
                if method == "GET":
                    self._send_json({"ok": True, "release_id": release_id, "parties": self.rights_clearance_store.list_parties(release_id)})
                    return
                if method == "POST":
                    party = self.rights_clearance_store.upsert_party(release_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "party": party}, status=HTTPStatus.CREATED)
                    return
                self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                return
            if len(parts) == 2 and parts[0] == "parties":
                if method not in {"POST", "PATCH"}:
                    self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                    return
                party = self.rights_clearance_store.upsert_party(release_id, {**self._read_json_body(), "party_id": parts[1]}, now=_utc_now())
                self._send_json({"ok": True, "release_id": release_id, "party": party})
                return
            if len(parts) >= 2 and parts[0] == "tracks":
                track_id = parts[1]
                action = parts[2] if len(parts) >= 3 else ""
                if not action:
                    if method == "GET":
                        record = self.rights_clearance_store.read_track(release_id, track_id, default={})
                        self._send_json({"ok": True, "release_id": release_id, "track_id": track_id, "rights": record})
                        return
                    if method in {"POST", "PATCH"}:
                        record = self.rights_clearance_store.upsert_track(release_id, track_id, self._optional_json_body(), now=_utc_now())
                        self._send_json({"ok": True, "release_id": release_id, "track_id": track_id, "rights": record})
                        return
                if action == "contributors":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    payload = self._optional_json_body()
                    contributors = payload.get("contributors") if isinstance(payload.get("contributors"), list) else payload if isinstance(payload, list) else []
                    record = self.rights_clearance_store.upsert_track(release_id, track_id, {"contributors": contributors}, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "track_id": track_id, "rights": record})
                    return
                if action == "sources":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    payload = self._optional_json_body()
                    sources = payload.get("source_usages") if isinstance(payload.get("source_usages"), list) else payload.get("sources") if isinstance(payload.get("sources"), list) else payload if isinstance(payload, list) else []
                    record = self.rights_clearance_store.upsert_track(release_id, track_id, {"source_usages": sources}, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "track_id": track_id, "rights": record})
                    return
                if action == "review":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    record = self.rights_clearance_store.review_track(release_id, track_id, self._read_json_body(), now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "track_id": track_id, "rights": record})
                    return
                if action == "reset-review":
                    if method != "POST":
                        self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
                        return
                    payload = self._optional_json_body()
                    reason = str(payload.get("reason") or "").strip()
                    if not reason:
                        self._send_error(HTTPStatus.BAD_REQUEST, "reason is required.")
                        return
                    record = self.rights_clearance_store.reset_track_review(release_id, track_id, reason=reason, now=_utc_now())
                    self._send_json({"ok": True, "release_id": release_id, "track_id": track_id, "rights": record})
                    return
            self._send_error(HTTPStatus.NOT_FOUND, "Rights clearance route not found.")
        except (ReleaseNotFoundError, RightsClearanceNotFoundError, FileNotFoundError) as exc:
            self._send_error(HTTPStatus.NOT_FOUND, str(exc))
        except (ReleaseStateError, RightsClearanceStateError) as exc:
            self._send_error(HTTPStatus.CONFLICT, str(exc))
        except (RightsClearanceError, ValueError) as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))

    def _renderer_profile_from_payload(self, payload: dict[str, Any] | None) -> Any | None:
        profile_id = str((payload or {}).get("profile_id") or "").strip()
        if not profile_id:
            return None
        return self.audio_profile_store.get_profile(profile_id)

    def _renderer_config_from_payload(self, payload: dict[str, Any] | None) -> Any | None:
        profile = self._renderer_profile_from_payload(payload)
        if profile is None:
            return None
        return profile.to_renderer_config()

    def _job_audio_artifact_stale_reasons(self, job: JobState) -> list[str]:
        run_dir = Path(job.output_dir)
        wav_path = run_dir / "renders" / "song.wav"
        midi_path = run_dir / "renders" / "song.mid"
        plan_path = run_dir / "data" / "song-plan.json"
        manifest = read_audio_artifact_manifest(run_dir / "renders" / AUDIO_ARTIFACT_FILENAME, default={})
        profile = None
        renderer = manifest.get("renderer") if isinstance(manifest.get("renderer"), dict) else {}
        profile_id = str(renderer.get("profile_id") or "")
        if profile_id.startswith("arp-"):
            try:
                profile = self.audio_profile_store.get_profile(profile_id)
            except AudioProfileError:
                profile = None
        return audio_artifact_stale_reasons_for_profile(manifest, wav_path=wav_path, midi_path=midi_path, song_plan_path=plan_path, profile=profile)

    def _ensure_release_export_mutable(self, release_id: str, *, document: Any | None = None) -> None:
        document = document or self.release_store.get_release(release_id)
        if document.status == "archived":
            raise ReleaseStateError("Archived releases are read-only.")
        if document.status == "signed":
            raise ReleaseStateError("Signed releases cannot rebuild export or ZIP. Reset signoff before exporting again.")

    def _handle_release_signoff(self, method: str, release_id: str) -> None:
        if method == "GET":
            signoff = self.release_store.read_signoff(release_id, default={})
            self._send_json({"ok": True, "release_id": release_id, "signoff": signoff, "summary": release_signoff_summary(signoff)})
            return
        if method != "POST":
            self._send_error(HTTPStatus.METHOD_NOT_ALLOWED, "Method not allowed.")
            return
        payload = self._optional_json_body()
        existing = self.release_store.read_signoff(release_id, default={})
        if existing:
            self._send_error(HTTPStatus.CONFLICT, "Release is already signed off. Reset signoff before signing again.")
            return
        document = self.release_store.get_release(release_id)
        report = self._get_or_refresh_release_qa(release_id, refresh=True, options={})
        force = bool(payload.get("force", False))
        acceptance_gate = self._release_acceptance_gate({**payload, "release_id": release_id, "force": force})
        audio_gate = self._release_audio_gate(release_id, payload)
        if audio_gate:
            acceptance_gate = dict(acceptance_gate or {})
            acceptance_gate["audio"] = audio_gate
            if audio_gate.get("status") == "failed":
                acceptance_gate["status"] = "failed"
                acceptance_gate["message"] = str(audio_gate.get("message") or "Release audio gate failed.")
        require_mastering_qa = bool(payload.get("require_mastering_qa", False))
        mastering_gate = self.mastering_store.gate(
            release_id,
            required=require_mastering_qa,
            profile_id=str(payload.get("mastering_profile_id") or "") or None,
            force=force,
        )
        if mastering_gate and require_mastering_qa:
            acceptance_gate = dict(acceptance_gate or {})
            acceptance_gate["mastering"] = mastering_gate
            if mastering_gate.get("status") == "failed":
                acceptance_gate["status"] = "failed"
                acceptance_gate["message"] = str(mastering_gate.get("message") or "Mastering QA gate failed.")
        require_encoded_audio = bool(payload.get("require_encoded_audio", False))
        required_encoded_profiles = normalize_required_profiles(payload.get("required_audio_format_profiles") or payload.get("audio_format_profiles") or [])
        encoded_gate = encoded_audio_gate(
            self.audio_encoding_store,
            release_id,
            required_profiles=required_encoded_profiles,
            required=require_encoded_audio,
            force=force,
        )
        if encoded_gate and require_encoded_audio:
            acceptance_gate = dict(acceptance_gate or {})
            acceptance_gate["encoded_audio"] = encoded_gate
            if encoded_gate.get("status") == "failed":
                acceptance_gate["status"] = "failed"
                acceptance_gate["message"] = str(encoded_gate.get("message") or "Encoded audio gate failed.")
        require_encoded_audio_review = bool(payload.get("require_encoded_audio_review", False))
        encoded_acceptance_gate = self.encoded_audio_acceptance_store.gate(
            release_id,
            required_profiles=required_encoded_profiles,
            required=require_encoded_audio_review,
            now=_utc_now(),
        )
        if encoded_acceptance_gate and require_encoded_audio_review:
            acceptance_gate = dict(acceptance_gate or {})
            acceptance_gate["encoded_audio_acceptance"] = encoded_acceptance_gate
            if encoded_acceptance_gate.get("status") == "failed":
                acceptance_gate["status"] = "failed"
                acceptance_gate["message"] = str(encoded_acceptance_gate.get("message") or "Encoded audio acceptance gate failed.")
        require_format_decision = bool(payload.get("require_format_decision", False))
        format_decision_gate = self.format_decision_store.gate(
            release_id,
            required=require_format_decision,
            session_id=str(payload.get("format_decision_session_id") or "") or None,
            required_profiles=required_encoded_profiles,
        )
        if format_decision_gate and require_format_decision:
            acceptance_gate = dict(acceptance_gate or {})
            acceptance_gate["format_decision"] = format_decision_gate
            if format_decision_gate.get("status") == "failed":
                acceptance_gate["status"] = "failed"
                acceptance_gate["message"] = str(format_decision_gate.get("message") or "Format decision gate failed.")
        require_rights_clearance = bool(payload.get("require_rights_clearance", False))
        rights_gate = self.rights_clearance_store.gate(release_id, required=require_rights_clearance, now=_utc_now())
        if rights_gate and require_rights_clearance:
            acceptance_gate = dict(acceptance_gate or {})
            acceptance_gate["rights_clearance"] = rights_gate
            if rights_gate.get("status") == "failed":
                acceptance_gate["status"] = "failed"
                acceptance_gate["message"] = str(rights_gate.get("message") or "Rights clearance gate failed.")
        if audio_gate.get("hard_block") and audio_gate.get("status") == "failed":
            self._send_json(
                {
                    "error": str(audio_gate.get("message") or "Release audio gate failed."),
                    "acceptance_gate": acceptance_gate,
                },
                status=HTTPStatus.CONFLICT,
            )
            return
        if mastering_gate.get("hard_block") and mastering_gate.get("status") == "failed":
            self._send_json(
                {
                    "error": str(mastering_gate.get("message") or "Mastering QA gate failed."),
                    "acceptance_gate": acceptance_gate,
                },
                status=HTTPStatus.CONFLICT,
            )
            return
        if encoded_gate.get("hard_block") and encoded_gate.get("status") == "failed":
            self._send_json(
                {
                    "error": str(encoded_gate.get("message") or "Encoded audio gate failed."),
                    "acceptance_gate": acceptance_gate,
                },
                status=HTTPStatus.CONFLICT,
            )
            return
        if encoded_acceptance_gate.get("hard_block") and encoded_acceptance_gate.get("status") == "failed":
            self._send_json(
                {
                    "error": str(encoded_acceptance_gate.get("message") or "Encoded audio acceptance gate failed."),
                    "acceptance_gate": acceptance_gate,
                },
                status=HTTPStatus.CONFLICT,
            )
            return
        if format_decision_gate.get("hard_block") and format_decision_gate.get("status") == "failed":
            self._send_json(
                {
                    "error": str(format_decision_gate.get("message") or "Format decision gate failed."),
                    "acceptance_gate": acceptance_gate,
                },
                status=HTTPStatus.CONFLICT,
            )
            return
        if rights_gate.get("hard_block") and rights_gate.get("status") == "failed":
            self._send_json(
                {
                    "error": str(rights_gate.get("message") or "Rights clearance gate failed."),
                    "acceptance_gate": acceptance_gate,
                },
                status=HTTPStatus.CONFLICT,
            )
            return
        hard_gate = acceptance_gate.get("planning_rule_impact") if isinstance(acceptance_gate.get("planning_rule_impact"), dict) else {}
        if hard_gate.get("hard_block") and hard_gate.get("status") == "failed":
            self._send_error(HTTPStatus.CONFLICT, str(hard_gate.get("message") or "Planning Rule Impact gate failed."))
            return
        if acceptance_gate.get("status") == "failed" and not force:
            self._send_error(HTTPStatus.CONFLICT, str(acceptance_gate.get("message") or "Acceptance release gate failed."))
            return
        if not release_qa_allows_signoff(report) and not force:
            self._send_error(HTTPStatus.CONFLICT, "Release QA gate failed. Refresh QA or pass force=true with override_reason.")
            return
        if force and not str(payload.get("override_reason") or "").strip():
            self._send_error(HTTPStatus.BAD_REQUEST, "override_reason is required when force=true.")
            return
        try:
            export_manifest = read_release_export_manifest(self.release_store, release_id)
        except FileNotFoundError:
            export_manifest = {}
        if require_mastering_qa:
            if not export_manifest:
                self._send_json(
                    {
                        "error": "Release Export has not been generated.",
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
            mastering_export_gate = self._release_mastering_export_gate(export_manifest, mastering_gate)
            if mastering_export_gate.get("status") == "failed":
                acceptance_gate = dict(acceptance_gate or {})
                acceptance_gate["mastering_export"] = mastering_export_gate
                self._send_json(
                    {
                        "error": str(mastering_export_gate.get("message") or "Release Export is stale. Rebuild export before signoff."),
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
        if require_encoded_audio:
            if not export_manifest:
                self._send_json(
                    {
                        "error": "Release Export has not been generated.",
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
            encoded_export_gate = self._release_encoded_audio_export_gate(export_manifest, encoded_gate)
            if encoded_export_gate.get("status") == "failed":
                acceptance_gate = dict(acceptance_gate or {})
                acceptance_gate["encoded_audio_export"] = encoded_export_gate
                self._send_json(
                    {
                        "error": str(encoded_export_gate.get("message") or "Release Export is stale. Rebuild export before signoff."),
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
        if require_encoded_audio_review:
            if not export_manifest:
                self._send_json(
                    {
                        "error": "Release Export has not been generated.",
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
        if require_format_decision:
            if not export_manifest:
                self._send_json(
                    {
                        "error": "Release Export has not been generated.",
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
            format_decision_export_gate = self._release_format_decision_export_gate(export_manifest, format_decision_gate)
            if format_decision_export_gate.get("status") == "failed":
                acceptance_gate = dict(acceptance_gate or {})
                acceptance_gate["format_decision_export"] = format_decision_export_gate
                self._send_json(
                    {
                        "error": str(format_decision_export_gate.get("message") or "Release Export is stale. Rebuild export before signoff."),
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
            encoded_acceptance_export_gate = self._release_encoded_audio_acceptance_export_gate(export_manifest, encoded_acceptance_gate)
            if encoded_acceptance_export_gate.get("status") == "failed":
                acceptance_gate = dict(acceptance_gate or {})
                acceptance_gate["encoded_audio_acceptance_export"] = encoded_acceptance_export_gate
                self._send_json(
                    {
                        "error": str(encoded_acceptance_export_gate.get("message") or "Release Export is stale. Rebuild export before signoff."),
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
        if require_rights_clearance:
            if not export_manifest:
                self._send_json(
                    {
                        "error": "Release Export has not been generated.",
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
            rights_export_gate = self._release_rights_clearance_export_gate(export_manifest, rights_gate)
            if rights_export_gate.get("status") == "failed":
                acceptance_gate = dict(acceptance_gate or {})
                acceptance_gate["rights_clearance_export"] = rights_export_gate
                self._send_json(
                    {
                        "error": str(rights_export_gate.get("message") or "Release Export is stale. Rebuild export before signoff."),
                        "acceptance_gate": acceptance_gate,
                    },
                    status=HTTPStatus.CONFLICT,
                )
                return
        if not export_manifest and not force:
            self._send_error(HTTPStatus.CONFLICT, "Release Export has not been generated.")
            return
        if export_manifest and not force:
            if export_manifest.get("source_hash") != report.get("source_hash"):
                self._send_error(HTTPStatus.CONFLICT, "Release Export is stale. Rebuild export before signoff.")
                return
            zip_summary = export_manifest.get("zip") if isinstance(export_manifest.get("zip"), dict) else {}
            zip_path = self.release_store.zip_path(release_id)
            if bool(payload.get("require_zip", True)) and not (zip_path.exists() and zip_path.is_file() and not zip_path.is_symlink() and zip_summary.get("entry_count")):
                self._send_error(HTTPStatus.CONFLICT, "Release ZIP has not been generated.")
                return
        try:
            pending_signoff = build_release_signoff_record(release=document, report=report, payload={**payload, "force": force}, export_manifest={}, now=_utc_now())
        except ValueError as exc:
            self._send_error(HTTPStatus.BAD_REQUEST, str(exc))
            return
        if acceptance_gate:
            pending_signoff["acceptance_gate"] = acceptance_gate
        self.release_store.write_signoff(release_id, {**pending_signoff, "export_manifest_hash": None})
        try:
            final_manifest = refresh_release_export_signoff_summary(self.release_store, release_id)
            final_manifest.pop("zip", None)
            final_hash = stable_hash(final_manifest)
            signoff = {**pending_signoff, "export_manifest_hash": final_hash}
            signoff = self.release_store.write_signoff(release_id, signoff)
            refresh_release_export_signoff_summary(self.release_store, release_id)
            build_release_export_zip(self.release_store, release_id, now=_utc_now(), allow_signed=True)
        except FileNotFoundError:
            signoff = self.release_store.write_signoff(release_id, pending_signoff)
        document = self.release_store.update_signoff_summary(release_id, release_signoff_summary(signoff))
        self.release_store.append_event(release_id, "release_force_signed" if force else "release_signed", {"status": report.get("status"), "forced": force})
        self._send_json({"ok": True, "release": document.to_dict(), "signoff": signoff, "summary": release_signoff_summary(signoff)})

    def _release_mastering_export_gate(self, export_manifest: dict[str, Any], mastering_gate: dict[str, Any]) -> dict[str, Any]:
        manifest_mastering = export_manifest.get("mastering") if isinstance(export_manifest.get("mastering"), dict) else {}
        required_fields = ("analysis_hash", "plan_hash", "selected_candidate_id", "selected_candidate_hash")
        missing_fields = [field for field in required_fields if not manifest_mastering.get(field)]
        mismatched_fields = [
            field
            for field in required_fields
            if str(manifest_mastering.get(field) or "") != str(mastering_gate.get(field) or "")
        ]
        manifest_status = str(manifest_mastering.get("status") or "")
        if manifest_status not in {"passed", "warning"}:
            mismatched_fields.append("status")
        failed = bool(missing_fields or mismatched_fields)
        return {
            "status": "failed" if failed else "passed",
            "hard_block": failed,
            "message": "Release Export is stale. Rebuild export before signoff." if failed else "Release Export contains current Mastering QA evidence.",
            "missing_fields": sorted(set(missing_fields)),
            "mismatched_fields": sorted(set(mismatched_fields)),
            "manifest_selected_candidate_id": manifest_mastering.get("selected_candidate_id"),
            "current_selected_candidate_id": mastering_gate.get("selected_candidate_id"),
            "manifest_status": manifest_status or "missing",
        }

    def _release_encoded_audio_export_gate(self, export_manifest: dict[str, Any], encoded_gate: dict[str, Any]) -> dict[str, Any]:
        manifest_encoded = export_manifest.get("encoded_audio") if isinstance(export_manifest.get("encoded_audio"), dict) else {}
        manifest_profiles = manifest_encoded.get("profiles") if isinstance(manifest_encoded.get("profiles"), list) else []
        by_profile = {str(row.get("profile_id") or ""): row for row in manifest_profiles if isinstance(row, dict)}
        missing: list[str] = []
        mismatched: list[str] = []
        for row in encoded_gate.get("profiles", []) if isinstance(encoded_gate.get("profiles"), list) else []:
            if not isinstance(row, dict):
                continue
            profile_id = str(row.get("profile_id") or "")
            manifest_row = by_profile.get(profile_id)
            if not manifest_row:
                missing.append(profile_id)
                continue
            for field in ("source_hash", "manifest_hash"):
                if str(manifest_row.get(field) or "") != str(row.get(field) or ""):
                    mismatched.append(f"{profile_id}:{field}")
            if str(manifest_row.get("status") or "") != "completed":
                mismatched.append(f"{profile_id}:status")
        failed = bool(missing or mismatched)
        return {
            "status": "failed" if failed else "passed",
            "hard_block": failed,
            "message": "Release Export is stale. Rebuild export before signoff." if failed else "Release Export contains current encoded audio evidence.",
            "missing_profiles": missing,
            "mismatched_profiles": sorted(set(mismatched)),
        }

    def _release_encoded_audio_acceptance_export_gate(self, export_manifest: dict[str, Any], acceptance_gate: dict[str, Any]) -> dict[str, Any]:
        manifest_acceptance = export_manifest.get("encoded_audio_acceptance") if isinstance(export_manifest.get("encoded_audio_acceptance"), dict) else {}
        missing: list[str] = []
        mismatched: list[str] = []
        if not manifest_acceptance:
            missing.append("encoded_audio_acceptance")
        summary: dict[str, Any] = {}
        release_id = str(export_manifest.get("release_id") or "")
        export_dir = self.release_store.export_dir(release_id)
        summary_path = str(manifest_acceptance.get("summary_path") or "encoded-audio-acceptance-summary.json")
        if manifest_acceptance:
            try:
                candidate = read_json(export_dir / summary_path)
                summary = candidate if isinstance(candidate, dict) else {}
            except Exception:
                missing.append(summary_path)
        if summary:
            expected_hash = str(manifest_acceptance.get("summary_hash") or "")
            actual_hash = encoded_audio_acceptance_summary_hash(summary)
            if not expected_hash or expected_hash != actual_hash or not encoded_audio_acceptance_summary_integrity_ok(summary):
                mismatched.append("summary_hash")
        elif manifest_acceptance:
            mismatched.append("summary")
        manifest_profiles = {str(item) for item in summary.get("required_profiles", []) if str(item).strip()} if isinstance(summary.get("required_profiles"), list) else {str(item) for item in manifest_acceptance.get("required_profiles", []) if str(item).strip()} if isinstance(manifest_acceptance.get("required_profiles"), list) else set()
        gate_profiles = {str(item) for item in acceptance_gate.get("required_profiles", []) if str(item).strip()} if isinstance(acceptance_gate.get("required_profiles"), list) else set()
        missing_profiles = sorted(gate_profiles - manifest_profiles)
        summary_tracks = summary.get("tracks") if isinstance(summary.get("tracks"), list) else []
        by_profile_track = {
            (str(row.get("profile_id") or ""), str(row.get("track_id") or "")): row
            for row in summary_tracks
            if isinstance(row, dict)
        }
        gate_summary = self.encoded_audio_acceptance_store.build_summary(release_id, required_profiles=sorted(gate_profiles), now=_utc_now())
        gate_tracks = gate_summary.get("tracks") if isinstance(gate_summary.get("tracks"), list) else []
        review_hashes = {
            str(row.get("review_id") or ""): {"path": str(row.get("path") or ""), "payload_hash": str(row.get("payload_hash") or "")}
            for row in manifest_acceptance.get("review_hashes", [])
            if isinstance(row, dict) and str(row.get("review_id") or "")
        }
        for row in gate_tracks:
            if not isinstance(row, dict):
                continue
            profile_id = str(row.get("profile_id") or "")
            track_id = str(row.get("track_id") or "")
            manifest_row = by_profile_track.get((profile_id, track_id))
            if not manifest_row:
                missing.append(f"{profile_id}/{track_id}")
                continue
            for field in ("status", "manifest_hash", "health_hash", "encoded_track_hash", "accepted_review_id"):
                if str(manifest_row.get(field) or "") != str(row.get(field) or ""):
                    mismatched.append(f"{profile_id}/{track_id}:{field}")
            review_id = str(row.get("accepted_review_id") or "")
            review_record = review_hashes.get(review_id) or {}
            review_path = str(review_record.get("path") or "")
            if not review_path:
                missing.append(f"{profile_id}/{track_id}:review")
                continue
            try:
                review = read_json(export_dir / review_path)
            except Exception:
                missing.append(review_path)
                continue
            if not isinstance(review, dict) or not encoded_audio_review_integrity_ok(review):
                mismatched.append(f"{profile_id}/{track_id}:review_integrity")
            if encoded_audio_review_integrity_hash(review if isinstance(review, dict) else {}) != str(review_record.get("payload_hash") or ""):
                mismatched.append(f"{profile_id}/{track_id}:review_hash")
        failed = bool(missing or mismatched or missing_profiles)
        return {
            "status": "failed" if failed else "passed",
            "hard_block": failed,
            "message": "Release Export is stale. Rebuild export before signoff." if failed else "Release Export contains current encoded audio acceptance evidence.",
            "missing": missing,
            "mismatched_fields": sorted(set(mismatched)),
            "missing_profiles": missing_profiles,
        }

    def _release_format_decision_export_gate(self, export_manifest: dict[str, Any], format_decision_gate: dict[str, Any]) -> dict[str, Any]:
        manifest_decision = export_manifest.get("format_decision") if isinstance(export_manifest.get("format_decision"), dict) else {}
        missing: list[str] = []
        mismatched: list[str] = []
        if not manifest_decision or manifest_decision.get("status") in {"", "missing"}:
            missing.append("format_decision")
        release_id = str(export_manifest.get("release_id") or "")
        export_dir = self.release_store.export_dir(release_id)
        report_path = str(manifest_decision.get("report_path") or "format-decision/decision-report.json")
        report: dict[str, Any] = {}
        try:
            candidate = read_json(export_dir / report_path)
            report = candidate if isinstance(candidate, dict) else {}
        except Exception:
            missing.append(report_path)
        expected_report_hash = str(format_decision_gate.get("report_hash") or "")
        manifest_report_hash = str(manifest_decision.get("report_hash") or "")
        if expected_report_hash and manifest_report_hash != expected_report_hash:
            mismatched.append("report_hash")
        if report and str(report.get("integrity_hash") or "") != expected_report_hash:
            mismatched.append("report_payload")
        selected = set(manifest_decision.get("selected_profiles", []) if isinstance(manifest_decision.get("selected_profiles"), list) else [])
        gate_required = set(format_decision_gate.get("required_profiles", []) if isinstance(format_decision_gate.get("required_profiles"), list) else [])
        missing_profiles = sorted(gate_required - selected)
        failed = bool(missing or mismatched or missing_profiles)
        return {
            "status": "failed" if failed else "passed",
            "hard_block": failed,
            "message": "Release Export is stale. Rebuild export before signoff." if failed else "Release Export contains current format decision evidence.",
            "missing": missing,
            "mismatched_fields": sorted(set(mismatched)),
            "missing_profiles": missing_profiles,
        }

